pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        address before;
        try c.owner() returns (address __r) { before = __r; } catch { return; }
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        bool reverted2;
        try c.transferOwnership(caller) { reverted2 = false; } catch { reverted2 = true; }
        assertTrue(reverted && reverted2 && c.owner() == before);
    }

    function testFuzz_run(address caller) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller);
